/** Build an environment that excludes inherited Git overrides and user configuration. */
function isolatedEnv(root) {
  const gcfg = path.join(root, 'gitconfig-empty');
  if (!fs.existsSync(gcfg)) fs.writeFileSync(gcfg, '');
  const env = {};
  // Pager cases declare their inherited PAGER explicitly through case.env.
  // A caller's pager must not silently change every Git query fixture.
  for (const [k, v] of Object.entries(process.env)) if (!/^GIT_/.test(k) && k !== 'CLAUDE_PROJECT_DIR' && k !== 'PAGER') env[k] = v;
  env.GIT_CONFIG_GLOBAL = gcfg;
  env.GIT_CONFIG_NOSYSTEM = '1';
  return env;
}

