function setupRepos() {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'git-guards-test-')));
  const env = isolatedEnv(root);
  const git = (cwd, ...args) => execFileSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@example.invalid', ...args], {
    cwd, env, stdio: ['ignore', 'pipe', 'pipe'],
  });
  const mk = (name, files) => {
    const d = path.join(root, name);
    fs.mkdirSync(d, { recursive: true });
    git(d, 'init', '-q');
    for (const [f, body] of Object.entries(files)) {
      fs.mkdirSync(path.dirname(path.join(d, f)), { recursive: true });
      fs.writeFileSync(path.join(d, f), body);
    }
    return d;
  };
  const dirs = {};
  dirs.clean = mk('clean', { 'a.txt': 'a\n' });
  fs.mkdirSync(path.join(dirs.clean, 'sub'), { recursive: true });

  git(dirs.clean, 'add', '--', 'a.txt');
  dirs.dirty = mk('dirty', { 'a.txt': 'a\n', '.env': '' });
  git(dirs.dirty, 'add', '--', 'a.txt', '.env');
  dirs.newline = mk('newline', { '.env\nleak': '' });
  git(dirs.newline, 'add', '--', '.env\nleak');
  dirs.spaces = mk('spaces', { 'ordinary file.txt': '' });
  git(dirs.spaces, 'add', '--', 'ordinary file.txt');
  dirs.tracked = mk('tracked', { 'a.txt': 'a\n', 'conf/dummy-token.json': '' });
  git(dirs.tracked, 'add', '--', 'a.txt', 'conf/dummy-token.json');
  git(dirs.tracked, 'commit', '-q', '-m', 'init');
  dirs.alias = mk('alias', { 'a.txt': 'a\n' });
  git(dirs.alias, 'add', '--', 'a.txt');
  git(dirs.alias, 'config', 'alias.ci', 'commit');
  // R30: a separate deterministic DUMMY commit whose selected path is prohibited.
  // Old fixture repositories and commands above keep their original semantics.
  dirs.cherry = mk('cherry', { 'a.txt': 'DUMMY ordinary\n' });
  const cherryGit = (...args) => execFileSync('git', ['-c', 'user.name=DUMMY',
    '-c', 'user.email=dummy@example.invalid', ...args], {
    cwd: dirs.cherry, env: { ...env, GIT_AUTHOR_DATE: '2026-10-15T04:00:00+09:00',
      GIT_COMMITTER_DATE: '2026-10-15T04:00:00+09:00' }, encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  }).trim();
  cherryGit('add', '--', 'a.txt');
  cherryGit('commit', '-q', '-m', 'DUMMY base');
  const cherryBaseOID = cherryGit('rev-parse', 'HEAD');
  fs.writeFileSync(path.join(dirs.cherry, '.env'), '');
  cherryGit('add', '--', '.env');
  cherryGit('commit', '-q', '-m', 'DUMMY prohibited filename fixture');
  const cherrySecretOID = cherryGit('rev-parse', 'HEAD');
  if (cherryGit('diff-tree', '--no-commit-id', '--name-status', '-r', cherrySecretOID) !== 'A\t.env') {
    throw new Error('DUMMY cherry fixture must select only the empty prohibited filename');
  }
  cherryGit('update-ref', 'refs/heads/dummy-selected', cherrySecretOID);
  cherryGit('reset', '--hard', cherryBaseOID);
// Root-owned public-runner insertion after existing cherry setup and before return.
// Uses setupRepos mk(), local EMPTY file and fixed DUMMY dates only; NEVER runs revert.
dirs.revert = mk('revert', { 'a.txt': 'DUMMY ordinary\n' });
const revertGit = (...args) => execFileSync('git', ['-c', 'user.name=DUMMY',
  '-c', 'user.email=dummy@example.invalid', ...args], {
  cwd: dirs.revert, env: { ...env, GIT_AUTHOR_DATE: '2026-10-15T04:00:00+09:00',
    GIT_COMMITTER_DATE: '2026-10-15T04:00:00+09:00' }, encoding: 'utf8',
  stdio: ['ignore', 'pipe', 'pipe'],
}).trim();
revertGit('add', '--', 'a.txt');
revertGit('commit', '-q', '-m', 'DUMMY base');
const revertBaseOID = revertGit('rev-parse', 'HEAD');
fs.writeFileSync(path.join(dirs.revert, '.env'), '');
revertGit('add', '--', '.env');
revertGit('commit', '-q', '-m', 'DUMMY prohibited filename fixture');
const revertEmptyAdditionOID = revertGit('rev-parse', 'HEAD');
if (revertEmptyAdditionOID !== cherrySecretOID) throw new Error('owned addition mapping differs');
revertGit('rm', '.env');
revertGit('-c', 'user.name=DUMMY Author', '-c', 'user.email=dummy@example.invalid', 'commit', '-m', 'DUMMY deletes EMPTY env');
const revertDeleteOID = revertGit('rev-parse', 'HEAD');
if (revertGit('diff-tree', '--no-commit-id', '--name-status', '-r', revertDeleteOID) !== 'D\t.env') throw new Error('invalid EMPTY deletion mapping');
// return DTO adds revertDeleteOID/revertBaseOID/revertEmptyAdditionOID.
// fill() adds 'revert' and 'revert_delete_oid', the latter -> repos.revertDeleteOID.
// Existing old dirs.cherry/commands/expectations remain byte/semantic unchanged.

  // R33-only deterministic DUMMY incoming-object fixture; the tested merge/rebase commands remain DATA.
  dirs.r33merge = mk('r33merge', { 'a.txt': 'DUMMY base\n' });
  const r33Git = (...args) => execFileSync('git', ['-c', 'user.name=DUMMY',
    '-c', 'user.email=dummy@example.invalid', ...args], {
    cwd: dirs.r33merge, env: { ...env, GIT_AUTHOR_DATE: '2026-10-15T04:00:00+09:00',
      GIT_COMMITTER_DATE: '2026-10-15T04:00:00+09:00' }, encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  }).trim();
  r33Git('add', '--', 'a.txt');
  r33Git('commit', '-q', '-m', 'DUMMY R33 base');
  const r33MergeBase = r33Git('rev-parse', 'HEAD');
  fs.writeFileSync(path.join(dirs.r33merge, '.env'), '');
  r33Git('add', '--', '.env');
  r33Git('commit', '-q', '-m', 'DUMMY R33 EMPTY env addition');
  r33Git('update-ref', 'refs/heads/topic', r33Git('rev-parse', 'HEAD'));
  r33Git('reset', '--hard', r33MergeBase);
  if (r33Git('diff', '--cached', '--name-only') !== '' ||
      fs.existsSync(path.join(dirs.r33merge, '.env')) ||
      r33Git('diff-tree', '--no-commit-id', '--name-status', '-r', 'topic') !== 'A\t.env')
    throw new Error('R33 DUMMY incoming-object fixture invalid');

  return { root, env, dirs, cherryBaseOID, cherrySecretOID, revertDeleteOID, revertBaseOID, revertEmptyAdditionOID };
}

/** Remove only the disposable fixture root created by setupRepos. */
function cleanupRepos(repos) {
  fs.rmSync(repos.root, { recursive: true, force: true });
}

/** Run a case through all guards, recording denials and hook execution failures. */
function runCase(hooksDir, c, repos, stopAtFirstDeny = false) {
  const fill = (s) => s.replace(/\{(clean|dirty|tracked|alias|newline|spaces|root|cherry|cherry_secret_oid|revert|revert_delete_oid)\}/g, (_m, k) => (k === 'root' ? repos.root : k === 'cherry_secret_oid' ? repos.cherrySecretOID : k === 'revert_delete_oid' ? repos.revertDeleteOID : repos.dirs[k]));
  const command = fill(c.cmd);
  const cwd = repos.dirs[c.cwd || 'clean'];
  const project = repos.dirs[c.project || 'clean'];
  // case に stdin があれば、hook 入力としてそのまま渡す（v3.5.4・JSON がオブジェクトでない入力の試験）。
  const input = c.stdin !== undefined ? c.stdin : JSON.stringify({ hook_event_name: 'PreToolUse', tool_name: 'Bash', tool_input: { command }, cwd });
  const denied = [];
  const broken = [];
  const reasonPrefixes = {};
  for (const h of HOOKS) {
    const r = spawnSync(process.execPath, [path.join(hooksDir, h)], {
      input, cwd: project, env: { ...repos.env, ...(c.env || {}), CLAUDE_PROJECT_DIR: project }, encoding: 'utf8', timeout: 20000,
    });
    if (r.error || r.status !== 0) { broken.push(`${h}: exit ${r.status}${r.error ? ` ${r.error.code}` : ''}`); continue; }
    if (!r.stdout) continue;
    let out;
    try { out = JSON.parse(r.stdout); } catch { broken.push(`${h}: JSON でない出力`); continue; }
    if (out && out.hookSpecificOutput && out.hookSpecificOutput.permissionDecision === 'deny') {
      denied.push(h);
      const reason = out.hookSpecificOutput.permissionDecisionReason;
      reasonPrefixes[h] = typeof reason === 'string' && reason.startsWith('[禁止] ') ? '[禁止] '
        : typeof reason === 'string' && reason.startsWith('[判断不能] ') ? '[判断不能] ' : null;
      if (stopAtFirstDeny) break;
    }
  }
  return { id: c.id, decision: denied.length ? 'deny' : 'allow', denied, broken, reasonPrefixes };
}

/** Validate CLI options, run the fixtures, and report decisions as text or JSON. */
function main() {
  const argv = process.argv.slice(2);
  const hi = argv.indexOf('--hooks-dir');
  if (hi >= 0 && (!argv[hi + 1] || argv[hi + 1].startsWith('--'))) {
    console.error('--hooks-dir needs a directory\nUsage: git-guards.test.cjs [--hooks-dir <dir>] [--json]');
    process.exit(2);
  }
  const hooksDir = path.resolve(hi >= 0 ? argv[hi + 1] : path.join(__dirname, '..'));
  const asJson = argv.includes('--json');
  const repos = setupRepos();
  let failed = 0;
  const results = [];
  try {
    for (const c of CASES) {
      const r = runCase(hooksDir, c, repos);
      r.expect = c.expect;
      const egressPrefix = r.reasonPrefixes['block-secret-egress.cjs'];
      r.ownEG = !r.denied.includes('block-secret-egress.cjs') ? 'ALLOW' :
        egressPrefix === '[禁止] ' ? 'FORBIDDEN' : egressPrefix === '[判断不能] ' ? 'UNKNOWN' : 'UNCLASSIFIED';
      r.ok = r.decision === c.expect && r.broken.length === 0 &&
        (!c.expectedOwnEG || r.ownEG === c.expectedOwnEG) &&
        (!c.denyBy || r.denied.includes(c.denyBy)) &&
        (!c.allowBy || HOOKS.includes(c.allowBy) && !r.denied.includes(c.allowBy)) &&
        Object.entries(c.expectReasonPrefixes || {}).every(([hook, prefix]) => r.reasonPrefixes[hook] === prefix);
      if (!r.ok) failed++;
      results.push(r);
    }
  } finally {
    cleanupRepos(repos);
  }
  if (asJson) {
    process.stdout.write(JSON.stringify({ hooksDir, total: results.length, failed, results }, null, 1) + '\n');
  } else {
    for (const r of results) {
      if (!r.ok) console.log(`✗ ${r.id}: expect ${r.expect} got ${r.decision} ${r.denied.join(',')} ${r.broken.join('; ')}`);
    }
    console.log(`${results.length - failed}/${results.length} ok`);
  }
  process.exitCode = failed ? 1 : 0;
}

